import numpy as np
from scipy.ndimage import gaussian_filter, median_filter
from skimage.restoration import denoise_bilateral

def apply_classical_filters(img):
    img = img.astype(np.float32)
    return {
        "gauss": gaussian_filter(img, sigma=1.5).astype(np.float32),
        "median": median_filter(img, size=3).astype(np.float32),
        "bilateral": denoise_bilateral(
            img, sigma_color=0.12, sigma_spatial=2.0, channel_axis=None
        ).astype(np.float32),
    }
